mapper.select:
SELECT bean_name, COUNT(*) AS log_count
FROM coffee_log
WHERE member_id = #{memberId}
  AND FORMATDATETIME(drink_date, 'yyyy-MM') = #{yearMonth}
GROUP BY bean_name
ORDER BY log_count DESC, bean_name
LIMIT #{limit}

SELECT artist_name, COUNT(*) AS log_count
FROM music_log
WHERE member_id = #{memberId}
  AND FORMATDATETIME(listened_date, 'yyyy-MM') = #{yearMonth}
GROUP BY artist_name
ORDER BY log_count DESC, artist_name
LIMIT #{limit}
